import{_ as e,o as s,c as a,aj as r}from"./chunks/framework.BwH0p-pt.js";const c=JSON.parse('{"title":"Publishing a Passport","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/passport/publishing.md","filePath":"3.0/passport/publishing.md","lastUpdated":1788942616000}'),o={name:"3.0/passport/publishing.md"};function n(i,t,d,h,l,p){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="publishing-a-passport" tabindex="-1">Publishing a Passport <a class="header-anchor" href="#publishing-a-passport" aria-label="Permalink to &quot;Publishing a Passport&quot;">​</a></h1><p>Publishing turns the current product data into a <strong>permanent, public passport version</strong>. Versions are never overwritten: each publish adds one, so you can always show what a passport said on a given date.</p><h2 id="check-a-product-first" tabindex="-1">Check a product first <a class="header-anchor" href="#check-a-product-first" aria-label="Permalink to &quot;Check a product first&quot;">​</a></h2><p>Open the product and click the <strong>Digital Product Passport</strong> card — it opens as a panel over the page. Per language it shows:</p><ul><li>the published version and when it went live,</li><li>how many <strong>required fields are still empty</strong> for that language,</li><li><strong>Preview</strong>, and once a version exists: <strong>Download QR code</strong> and the signed <strong>Operator</strong> and <strong>Authority</strong> links.</li></ul><p><strong>Preview</strong> renders the passport from the product&#39;s current data without publishing anything. Nothing public exists yet and no file is written.</p><h2 id="publish" tabindex="-1">Publish <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Publish&quot;">​</a></h2><p>From the product&#39;s passport card, publish the languages you need. Publishing is queued, so the version appears once the queue processes it.</p><p>You can also publish in bulk from <strong>Catalog → Products</strong> (select products → <em>Publish Digital Product Passport</em>), or refresh already-published passports in bulk from <strong>Catalog → Passports</strong> (<em>Republish selected</em>).</p><h3 id="why-a-language-may-refuse-to-publish" tabindex="-1">Why a language may refuse to publish <a class="header-anchor" href="#why-a-language-may-refuse-to-publish" aria-label="Permalink to &quot;Why a language may refuse to publish&quot;">​</a></h3><p>A language publishes only when every <strong>required</strong> field on its template resolves to a value <strong>in that language</strong>. The passport card names the fields that are missing, so a German passport can be live while Polish waits for two translations.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is deliberate. An incomplete passport in a market is a non-compliant passport in that market, and it is cheaper to catch here than at a border.</p></div><h2 id="what-the-public-sees" tabindex="-1">What the public sees <a class="header-anchor" href="#what-the-public-sees" aria-label="Permalink to &quot;What the public sees&quot;">​</a></h2><p>Each published passport has a permanent address per language, and:</p><table tabindex="0"><thead><tr><th>Surface</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Passport page</strong></td><td>The human-readable page: identification block, then your template&#39;s sections in order. It sets no cookies and runs no trackers.</td></tr><tr><td><strong>QR code</strong></td><td>An SVG for print or packaging, encoding the passport address (or its GS1 Digital Link when a GTIN is set).</td></tr><tr><td><strong>Machine-readable data</strong></td><td>The same passport as structured data for systems that consume it, both embedded in the page and served on request.</td></tr><tr><td><strong>GS1 Digital Link</strong></td><td>When a field carries the <strong>GTIN</strong> role, scanning a standard GS1 barcode resolves to the passport. UnoPim also checks the GTIN when the product is saved — a value with the wrong length or check digit is rejected, so a bad barcode never reaches print.</td></tr></tbody></table><h3 id="access-tiers" tabindex="-1">Access tiers <a class="header-anchor" href="#access-tiers" aria-label="Permalink to &quot;Access tiers&quot;">​</a></h3><p>Only <strong>Consumer</strong> fields appear on the public page. <strong>Operator</strong> and <strong>Authority</strong> fields are served solely through the signed links from the product&#39;s passport card, which expire. A tampered or hand-made link reveals nothing.</p><h2 id="version-history-withdrawal-and-erasure" tabindex="-1">Version history, withdrawal and erasure <a class="header-anchor" href="#version-history-withdrawal-and-erasure" aria-label="Permalink to &quot;Version history, withdrawal and erasure&quot;">​</a></h2><p>From <strong>Catalog → Passports</strong>:</p><ul><li><strong>Version history</strong> — every version per language, who published it and when, and <strong>Re-publish</strong> to make an older version current again (it is copied forward, never edited).</li><li><strong>Withdraw</strong> — takes the passport off the public web and shows a withdrawal notice instead. <strong>Reinstate</strong> puts it back; both are also available as bulk actions on the grid.</li><li><strong>Views</strong> — the grid counts how often each passport has been opened by the public.</li><li><strong>Redact</strong> — erases the stored content of a version for a GDPR request, keeping the record that it existed. Redaction is one-way and is done through the REST API — ask your technical team.</li></ul><h2 id="settings-that-affect-publishing" tabindex="-1">Settings that affect publishing <a class="header-anchor" href="#settings-that-affect-publishing" aria-label="Permalink to &quot;Settings that affect publishing&quot;">​</a></h2><p>In <a href="./../configuration/system-settings.html">System Settings</a> (<strong>Configuration → System Settings</strong>), the <strong>Digital Product Passport</strong> section has two rows:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Product Passport → Enabled</strong></td><td>Turns the whole feature, its menu and the product card on or off.</td></tr><tr><td><strong>Product Passport → Publish automatically on save</strong></td><td>Publishes a version whenever a saved product is complete enough. Off by default — publishing is a legal commitment, not a save side effect.</td></tr><tr><td><strong>Product Passport → Economic Operator Name / Address / EU Authorised Representative</strong></td><td>Shown on every passport; the ESPR requires the responsible operator to be identifiable.</td></tr><tr><td><strong>Publication → Enabled</strong></td><td>Serves the public pages. Off means passports exist but every public address returns &quot;not found&quot;.</td></tr><tr><td><strong>Publication → Base URL</strong></td><td>The public address passports are served from, printed into QR codes and shareable links. Blank means your site&#39;s own domain.</td></tr><tr><td><strong>Publication → Allow search engine indexing</strong></td><td>Off by default — passports are reachable by link and QR code but stay out of search results until you turn this on.</td></tr><tr><td><strong>Publication → Cache TTL / Rate Limit</strong></td><td>How long a shared cache may reuse a page, and how many requests a visitor may make per minute.</td></tr><tr><td><strong>Publication → GS1 Digital Link passport channel</strong></td><td>Which channel a scanned GS1 barcode resolves to when one product is published on several channels.</td></tr></tbody></table>',23)])])}const g=e(o,[["render",n]]);export{c as __pageData,g as default};
